 const [cloudLastRevision,setCloudLastRevision]=useState(()=>{const n=Number(localStorage.getItem('nox-haven:last-cloud-revision:v1'));return Number.isSafeInteger(n)&&n>=0?n:0;});
 const [settings,setSettings]=useState(false);
 const [storageReport,setStorageReport]=useState<{usage:number|null;quota:number|null;persistent:boolean|null;message:string}|null>(null);
