 useEffect(()=>{const flush=()=>{const snapshot=emergencySnapshotRef.current;saveEmergencySnapshot(snapshot.data,snapshot.preferences);};const onVisibility=()=>{if(document.visibilityState==='hidden')flush();};window.addEventListener('pagehide',flush);document.addEventListener('visibilitychange',onVisibility);return()=>{window.removeEventListener('pagehide',flush);document.removeEventListener('visibilitychange',onVisibility);};},[]);
 useEffect(()=>{try{if(import.meta.env.VITE_SUPABASE_URL&&import.meta.env.VITE_SUPABASE_ANON_KEY)configureCloudSync({url:import.meta.env.VITE_SUPABASE_URL,anonKey:import.meta.env.VITE_SUPABASE_ANON_KEY});setCloudStatus(getCloudSessionStatus());if(import.meta.env.VITE_SUPABASE_URL&&import.meta.env.VITE_SUPABASE_ANON_KEY)void refreshCloudSession().then(()=>setCloudStatus(getCloudSessionStatus()));}catch(error){setCloudMessage(error instanceof Error?error.message:'Configuration cloud invalide.');}},[]);
 useEffect(()=>subscribeToRemoteChanges(kind=>{setStorageConflict(true);setNotice(kind==='data'?'NOX HAVEN a été modifié dans un autre onglet. Recharge cette page avant de continuer pour éviter un écrasement.':'Les préférences ont changé dans un autre onglet. Recharge cette page avant de continuer.');}),[]);
 useEffect(()=>{let active=true;loadPrimaryData().then(result=>{if(!active)return;setData(result.data);setProfileReady(result.preferences.profileReady);setChapterProgress(result.preferences.chapterProgress);setTargetAverage(result.preferences.targetAverage);setSetupTarget(result.preferences.targetAverage===null?'':String(result.preferences.targetAverage));setWeeklyGoal(result.preferences.weeklyGoal);setDailyCapacity(result.preferences.dailyCapacity);setDark(result.preferences.dark);setStorageMode(result.persistent?'indexeddb':'fallback');setDataReady(true);void requestPersistentStorage();if(result.migrated||result.preferencesMigrated)setNotice(result.persistent?'Tes données ont été restaurées et sécurisées dans le stockage local.':'Tes données ont été restaurées depuis la copie de secours locale. Pense à exporter une sauvegarde.');}).catch(error=>{console.warn('NOX HAVEN IndexedDB:',error);if(!active)return;setStorageMode('error');setDataReady(false);setNotice('Impossible de lire le stockage NOX HAVEN. Aucune sauvegarde automatique ne sera effectuée afin de protéger tes données.');});return()=>{active=false;};},[]);
 useEffect(()=>{if(!dataReady||storageConflict)return;let active=true;if(storageMode==='indexeddb'){savePrimaryData(data).catch(error=>{console.error('NOX HAVEN save:',error);if(active)setNotice('La sauvegarde IndexedDB a échoué. Exporte tes données avant de continuer.');});}else if(storageMode==='fallback'){try{saveLegacyData(data);}catch{setNotice('Sauvegarde locale impossible : exporte tes données.');}}return()=>{active=false;};},[data,dataReady,storageMode,storageConflict]);
 useEffect(()=>{if(!dataReady||storageConflict)return;let active=true;const preferences={profileReady,chapterProgress,targetAverage,weeklyGoal,dailyCapacity,dark};if(storageMode==='indexeddb'){savePrimaryPreferences(preferences).catch(error=>{console.error('NOX HAVEN preferences:',error);if(active)setNotice('La sauvegarde des préférences a échoué. Une copie locale de secours a été conservée si le navigateur l’autorise.');});}else if(storageMode==='fallback'){try{saveLegacyPreferences(preferences);}catch{setNotice('Sauvegarde des préférences impossible : exporte tes données.');}}return()=>{active=false;};},[dataReady,storageMode,profileReady,chapterProgress,targetAverage,weeklyGoal,dailyCapacity,dark,storageConflict]);
 useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light';if(dataReady&&storageMode==='fallback')localStorage.setItem('studyflow_theme',dark?'dark':'light');},[dark,dataReady,storageMode]);
